def load_development(panel: Path, settlements: Path, registration: dict):
    spec = registration['data']
    panel_bytes, settlement_bytes = (panel.read_bytes(), settlements.read_bytes())
    if hashlib.sha256(panel_bytes).hexdigest() != spec['panelSha256'] or hashlib.sha256(settlement_bytes).hexdigest() != spec['settlementsSha256']:
        raise ValueError('only exact registered development bytes are permitted')
    bars = pd.read_csv(BytesIO(panel_bytes))
    events = pd.read_csv(BytesIO(settlement_bytes))
    if list(bars.columns) != ['symbol', 'openTime', 'closeTime', 'close']:
        raise ValueError('panel schema')
    if sorted(bars.symbol.unique()) != spec['symbols'] or sorted(events.symbol.unique()) != spec['symbols']:
        raise ValueError('symbol coverage')
    prices, funding = ({}, {})
    times = np.arange(spec['startOpenTime'], spec['endOpenTime'] + 1, spec['intervalMilliseconds'], dtype=np.int64)
    for symbol in spec['symbols']:
        rows = bars[bars.symbol == symbol]
        if len(rows) != spec['rowsPerSymbol'] or not np.array_equal(rows.openTime, times):
            raise ValueError('registered grid')
        closes = times + spec['intervalMilliseconds'] - 1
        if not np.array_equal(rows.closeTime, closes):
            raise ValueError('close timestamps')
        p = rows.close.to_numpy(dtype=float)
        if not np.isfinite(p).all() or np.any(p <= 0):
            raise ValueError('invalid price')
        f = np.zeros(len(p))
        es = events[events.symbol == symbol]
        if not np.isfinite(es[['fundingTime', 'fundingRate', 'resolvedMarkPrice']].to_numpy()).all():
            raise ValueError('invalid funding')
        if np.any(es.resolvedMarkPrice <= 0) or np.any(np.diff(es.fundingTime) <= 0):
            raise ValueError('funding identity/order')
        for event in es.itertuples():
            j = int(np.searchsorted(closes, event.fundingTime, side='left'))
            if j >= len(f):
                raise ValueError('funding beyond development')
            f[j] += event.fundingRate * event.resolvedMarkPrice
        p.setflags(write=False)
        f.setflags(write=False)
        prices[symbol], funding[symbol] = (p, f)
    return (prices, funding, times)

sequential_env.py.Scale.__post_init__:
def __post_init__(self) -> None:
    snapshots = {}
    for name in ('mean', 'std', 'low', 'high'):
        value = getattr(self, name)
        if not _real_series(value) or value.shape != (6,):
            raise ValueError('invalid scale parameter shape or type')
        with np.errstate(over='ignore', invalid='ignore'):
            snapshot = np.frombuffer(np.asarray(value, dtype=float).tobytes(), dtype=float)
        if not _feature_vector(snapshot):
            raise ValueError('non-finite scale parameter')
        snapshots[name] = snapshot
    if np.any(snapshots['std'] <= 0) or np.any(snapshots['low'] > snapshots['high']):
        raise ValueError('invalid scale deviation or support bounds')
    for name, value in snapshots.items():
        object.__setattr__(self, name, value)

sequential_env.py.Scale.transform:
def transform(self, x: np.ndarray) -> np.ndarray:
    if not _feature_vector(x):
        raise ValueError('invalid observation')
    with np.errstate(over='ignore', invalid='ignore', divide='ignore'):
        result = (np.asarray(x, dtype=float) - self.mean) / self.std
    if not _feature_vector(result):
        raise ValueError('non-finite normalized observation')
    return result

sequential_env.py.collect:
def collect(prices: dict[str, np.ndarray], funding: dict[str, np.ndarray], scale: Scale, horizon: int, seed: int, count: int, policy=None, execution: Execution=Execution()) -> dict:
    """Training-only prefixes physically bound every replay and episode."""
    if not all((_integer(v) for v in (horizon, seed, count))) or horizon not in (1, 3, 6) or seed < 0 or (count <= 0):
        raise ValueError('invalid collection horizon, seed or transition budget')
    if not isinstance(prices, dict) or not isinstance(funding, dict) or (not prices) or (set(prices) != set(funding)) or any((not isinstance(s, str) or not s for s in prices)):
        raise ValueError('invalid collection symbol coverage')
    for symbol, p in prices.items():
        f = funding[symbol]
        if not _real_series(p) or not _real_series(f) or len(p) != len(f) or (len(p) <= 120):
            raise ValueError('invalid collection series or insufficient episode history')
    horizon, seed, count = (int(horizon), int(seed), int(count))
    rng = np.random.default_rng(seed)
    symbols = sorted(prices)
    rows, episodes, env, starts = ([], [], None, 0)
    while len(rows) < count:
        if env is None or env.done:
            symbol = symbols[int(rng.integers(len(symbols)))]
            p = prices[symbol]
            start = int(rng.integers(24, len(p) - 96))
            env = Replay(p, funding[symbol], start, start + 97, horizon, scale, execution, enabled=True)
            starts += 1
        s = env.observation()
        if s is None:
            raise ValueError('invalid training observation')
        probs = np.full(3, 1 / 3) if policy is None else policy(s)
        if not _real_series(probs) or probs.shape != (3,) or (not np.isfinite(probs).all()) or np.any(probs < 0) or (not np.isclose(probs.sum(), 1)):
            raise ValueError('invalid behavior probabilities')
        a = int(rng.choice(3, p=probs))
        left = env.t
        nxt, reward, done = env.step(float(ACTIONS[a]))
        _admit_training_transition(env, left, nxt, reward, done)
        rows.append((s, a, reward, np.zeros(FEATURE_COUNT) if nxt is None else nxt, done, probs[a]))
        if done:
            episodes.append({'return': env.equity - 1, 'failure': env.failure})
    return {'s': np.array([r[0] for r in rows]), 'a': np.array([r[1] for r in rows]), 'r': np.array([r[2] for r in rows]), 'next': np.array([r[3] for r in rows]), 'done': np.array([r[4] for r in rows]), 'prob': np.array([r[5] for r in rows]), 'episodes': episodes, 'episodeAccountingV2': {'collections': 1, 'started': starts, 'completed': len(episodes), 'truncated': int(not env.done), 'decisions': len(rows)}}
